      "Posez les carrés de dacquoise aux noisettes/praliné feuilleté noisette dans les caissettes papier (Réf : 800). Dans la cuve du batteur munie du fouet, foisonnez la chantilly au chocolat au lait ; pour cela elle doit être très froide (entre 2°C et 4°C). A l’aide d’une poche munie d’une douille N°9, dressez un léger point de chantilly au chocolat au lait sur les carrés, posez les carrés de fines feuilles de chocolat au lait et de ganache au chocolat au lait en les appuyant. Dressez deux boudins de chantilly au chocolat au lait côte à côte. Terminez en posant un carré de fines feuilles de chocolat au lait.",
      "NB : Attention, la chantilly au chocolat au lait foisonne et épaissit très vite",
      "Finition",
      "A l’aide d’une saupoudreuse, saupoudrez de caco poudre.",
      "Conservation",
      "1 jour",
      "Conseils de consommation",
      "A garder au réfrigérateur jusqu’à consommation, il est très important de consommer ce gâteau froid.",
      "Boissons conseillées",
      "Eau, Muscat Corse, un vin italien façon Marsala : Morce di Luce.",
      "Notes, conseils et astuces",
      "Toute la conception de ce gâteau est basée sur une mise en valeur du chocolat au lait et sur une variation des textures (croustillante, craquante, moelleuse et fondante) et donc des sensations. Pour une mise en valeur du chocolat au lait, il est important qu’il soit sensuel.",
      "Tableau récapitulatif de poids",
