      "Assemblage",
      "Pour les individuels : à l’aide d’une poche, garnissez les moules Flexipan en forme de dôme au tiers de la hauteur avec de la crème mousseline citron. A l’aide d’une grosse cuillère, masquez grossièrement les moules avant de poser le premier disque de biscuit pain d’épices dans le fond en appuyant légèrement. Pochez une pointe de crème mousseline citron, posez le carré de fruits d’hiver à la gelée de citrons et d’oranges. Garnissez jusqu’à 5 mm en dessous du bord avec de la crème mousseline citron et posez le second disque de biscuit pain d’épices. Surgelez pendant 3 heures. Démoulez et stockez sous film au congélateur.",
      "Pour les 3 / 4 personnes : dans un moule inox à dôme de 14cm, à l’aide d’une poche, garnissez de 45 g de crème mousseline citron, posez le biscuit pain d’épices de 4 cm, appuyez afin de faire remonter la crème, garnissez de 45 g de crème mousseline citron, posez le disque de fruits d’hiver à la gelée de citrons et d’oranges de 8 cm, garnissez de 90 g de crème mousseline citron, posez le biscuit  pain d’épices de 9 cm, garnissez de 100 g de crème mousseline citron, posez le disque de fruits d’hiver à la gelée de citrons et d’oranges de 12 cm, garnissez de 50 g de crème mousseline citron et terminez par le biscuit pain d’épices de 13 cm. Surgelez pendant 2 heures au moins.",
