      "Pour les 10/12 personnes : dans un moule inox à dôme de 18cm, à l’aide d’une poche, garnissez de crème mousseline citron, posez le biscuit pain d’épices de 12 cm, appuyez afin de faire remonter la crème,  garnissez crème mousseline citron, posez le disque de fruits d’hiver à la gelée de citrons et d’oranges de 14 cm, garnissez de crème mousseline citron, posez le biscuit pain d’épices de 15 cm, garnissez de crème mousseline citron, posez le disque de fruits d’hiver à la gelée de citrons et d’oranges de 16 cm, garnissez de crème mousseline citron et terminez par le biscuit pain d’épices de 17 cm. Surgelez pendant 2 heures au moins.",
